package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; import java.math.*; @Service public class BillService{private final BillRepository r;private final PatientRepository pr;public BillService(BillRepository r,PatientRepository pr){this.r=r;this.pr=pr;} private Bill find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Bill not found"));} private BillDTO dto(Bill e){return BillDTO.builder().id(e.getId()).amount(e.getAmount()).status(e.getStatus()).billDate(e.getBillDate()).patientId(e.getPatient().getId()).build();} private void apply(Bill e,BillDTO d){Patient p=pr.findById(d.getPatientId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));e.setAmount(d.getAmount());e.setStatus(d.getStatus());e.setBillDate(d.getBillDate());e.setPatient(p);} public BillDTO create(BillDTO d){Bill e=new Bill();apply(e,d);return dto(r.save(e));} public List<BillDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public BillDTO get(Long id){return dto(find(id));} public BillDTO update(Long id,BillDTO d){Bill e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Bill e=find(id);e.setIsActive(false);r.save(e);} public List<BillDTO> unpaid(){return r.findByStatusIgnoreCaseAndIsActiveTrue("UNPAID").stream().map(this::dto).toList();} public BigDecimal total(Long id){return r.findByIsActiveTrue().stream().filter(b->b.getPatient().getId().equals(id)).map(Bill::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}}
